fieldlist.field:
page = PAGE

page.10 = FLUIDTEMPLATE
page.10 {
  dataProcessing.10 = language-menu
  dataProcessing.10 {
    languages = auto
    as = languageNavigation
  }
  template = TEXT
  template.value (
    <f:for each="{languageNavigation}" as="item">
      <a href="{item.link}" hreflang="{item.hreflang}">{item.navigationTitle}</a>
    </f:for>
  )
}

page.20 = CONTENT
page.20 {
  table = tt_content
  select {
    orderBy = sorting
    where = {#colPos}=0
  }
}
